#include "stdlib/blas/ext/base/ndarray/swhere.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <sys/time.h>

#define NAME "swhere"
#define ITERATIONS 1000000
#define REPEATS 3
#define MIN 1
#define MAX 6

/**
* Returns a clock time in seconds.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Runs a benchmark.
*
* @param iterations    number of iterations
* @param len           array length
* @return              elapsed time in seconds, or -1.0 if allocation fails
*/
static double benchmark( int iterations, int len ) {
	const struct ndarray *arrays[ 4 ];
	int64_t cstrides[] = { STDLIB_NDARRAY_BOOL_BYTES_PER_ELEMENT };
	int64_t strides[] = { STDLIB_NDARRAY_FLOAT32_BYTES_PER_ELEMENT };
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };
	int64_t shape[] = { len };
	struct ndarray *c = NULL;
	struct ndarray *x = NULL;
	struct ndarray *y = NULL;
	struct ndarray *out = NULL;
	bool *condition;
	float *dataX;
	float *dataY;
	float *dataOut;
	double elapsed;
	double start;
	int i;

	condition = (bool *)malloc( len * sizeof( bool ) );
	dataX = (float *)malloc( len * sizeof( float ) );
	dataY = (float *)malloc( len * sizeof( float ) );
	dataOut = (float *)malloc( len * sizeof( float ) );
	if ( condition == NULL || dataX == NULL || dataY == NULL || dataOut == NULL ) {
		elapsed = -1.0;
		goto cleanup;
	}
	for ( i = 0; i < len; i++ ) {
		condition[ i ] = (bool)( rand() & 1 );
		dataX[ i ] = (float)rand() / RAND_MAX;
		dataY[ i ] = (float)rand() / RAND_MAX;
		dataOut[ i ] = 0.0f;
	}
	c = stdlib_ndarray_allocate( STDLIB_NDARRAY_BOOL, (uint8_t *)condition, 1, shape, cstrides, 0, STDLIB_NDARRAY_ROW_MAJOR, STDLIB_NDARRAY_INDEX_ERROR, 1, submodes ); // cppcheck-suppress invalidPointerCast
	x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)dataX, 1, shape, strides, 0, STDLIB_NDARRAY_ROW_MAJOR, STDLIB_NDARRAY_INDEX_ERROR, 1, submodes ); // cppcheck-suppress invalidPointerCast
	y = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)dataY, 1, shape, strides, 0, STDLIB_NDARRAY_ROW_MAJOR, STDLIB_NDARRAY_INDEX_ERROR, 1, submodes ); // cppcheck-suppress invalidPointerCast
	out = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)dataOut, 1, shape, strides, 0, STDLIB_NDARRAY_ROW_MAJOR, STDLIB_NDARRAY_INDEX_ERROR, 1, submodes ); // cppcheck-suppress invalidPointerCast
	if ( c == NULL || x == NULL || y == NULL || out == NULL ) {
		elapsed = -1.0;
		goto cleanup;
	}
	arrays[ 0 ] = c;
	arrays[ 1 ] = x;
	arrays[ 2 ] = y;
	arrays[ 3 ] = out;

	start = tic();
	for ( i = 0; i < iterations; i++ ) {
		stdlib_blas_ext_swhere( arrays );
		if ( dataOut[ 0 ] != dataOut[ 0 ] ) {
			break;
		}
	}
	elapsed = tic() - start;
	if ( i != iterations ) {
		elapsed = -1.0;
	}

cleanup:
	stdlib_ndarray_free( c );
	stdlib_ndarray_free( x );
	stdlib_ndarray_free( y );
	stdlib_ndarray_free( out );
	free( condition );
	free( dataX );
	free( dataY );
	free( dataOut );
	return elapsed;
}

/**
* Main execution sequence.
*
* @return exit status
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int i;
	int j;

	srand( time( NULL ) );
	printf( "TAP version 13\n" );
	count = 0;
	len = 1;
	for ( i = MIN; i <= MAX; i++ ) {
		len *= 10;
		iter = ITERATIONS / ( len / 10 );
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:len=%d\n", NAME, len );
			elapsed = benchmark( iter, len );
			if ( elapsed < 0.0 ) {
				printf( "not ok %d benchmark failed\n", count );
				return 1;
			}
			printf( "  ---\n  iterations: %d\n  elapsed: %0.9f\n  rate: %0.9f\n  ...\n", iter, elapsed, (double)iter/elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	printf( "1..%d\n# total %d\n# pass  %d\n#\n# ok\n", count, count, count );
	return 0;
}
